.strike-overlay,.modal-backdrop{position:fixed;inset:0;display:none;align-items:center;justify-content:center;padding:20px;background:#100d0be8;backdrop-filter:blur(7px);z-index:20}.strike-overlay.open,.modal-backdrop.open{display:flex;animation:fade .2s}.strike-card,.result-card{width:min(440px,100%);padding:30px;background:linear-gradient(145deg,#30251d,#211b17);border:1px solid #6b4a31;border-radius:10px;text-align:center;box-shadow:0 25px 100px #000b}.strike-card h2,.result-card h2{font:600 25px var(--display);margin-bottom:8px}.strike-card>p:not(.eyebrow),.result-card>p:not(.eyebrow){font-size:11px;color:#b1a393;line-height:1.55}.strike-card .eyebrow,.result-card .eyebrow{margin-bottom:9px}.timing-meter{height:20px;border-radius:12px;background:linear-gradient(90deg,#763f30,#b95d38,#b99655,#bb6541,#773e30);position:relative;margin:31px 0 7px;border:2px solid #4d3b2e;box-shadow:inset 0 2px 6px #100b08}.sweet-zone{position:absolute;left:42%;width:16%;top:0;bottom:0;background:#c5c08380;border-left:1px solid #e3dc9b;border-right:1px solid #e3dc9b;box-shadow:0 0 11px #eddb86}.timing-marker{position:absolute;top:-7px;bottom:-7px;width:4px;left:0;background:white;box-shadow:0 0 10px #fff,0 0 18px #ffa253;border-radius:3px}.timing-labels{display:flex;justify-content:space-between;font-size:7px;letter-spacing:.8px;color:#9e8e7c}.strike-button{margin-top:24px;width:100%;height:49px;border:1px solid #e4a263;border-radius:5px;background:linear-gradient(100deg,#d67e40,#b54f2f);color:#fff2df;font:700 11px var(--sans);letter-spacing:1px;cursor:pointer;box-shadow:0 0 22px #bd552c3a}.strike-button span{margin-left:10px}.strike-card>small{display:block;color:#85786a;font-size:8px;margin-top:12px}.result-card{position:relative}.modal-close{position:absolute;right:13px;top:11px;background:none;border:0;color:#a89a87;font-size:23px;cursor:pointer}.result-icon{display:grid;place-items:center;margin:0 auto 15px;width:55px;height:55px;border-radius:50%;background:#75432644;border:1px solid #b67748;color:#f2b873;font-size:25px;box-shadow:0 0 25px #e27e3a32}.result-card h2{margin-bottom:9px}.result-item{padding:12px;margin:17px 0;border:1px solid #544330;border-radius:5px;background:#ffffff06;color:#e1c49b;font:600 12px var(--display)}.result-card>.primary-button{margin-top:3px}.arena-stage.victory .player-fighter{animation:bounce .5s}@keyframes bounce{50%{transform:translateY(-13px)}}.arena-stage.defeat{filter:saturate(.6)}.shake{animation:shake .3s}@keyframes shake{25%{transform:translateX(-5px)}75%{transform:translateX(5px)}}
@media(max-width:850px){.game-shell{padding:0 24px}.intro-row{align-items:flex-start;gap:15px}.reputation{min-width:245px}.forge-layout,.arena-layout{grid-template-columns:1fr minmax(255px,.75fr);gap:12px}.recipe-stats{gap:10px}.arena-stage{height:250px}.fighter-emoji{font-size:62px}}
@media(max-width:650px){.game-shell{padding:0 14px}.topbar{height:62px}.brand{font-size:12px}.brand-mark{width:26px;height:26px}.season-tag{font-size:8px;letter-spacing:.6px}.wallet{font-size:12px}.intro-row{display:block;padding:26px 0 20px}.intro-copy{font-size:11px}.reputation{margin-top:17px;width:100%;min-width:0;padding:9px 12px}.rep-track{width:110px}.tabs{margin:0 -14px 14px;padding:0 8px;justify-content:space-around}.tab{padding:0 10px;font-size:8px;letter-spacing:.6px}.tab span:first-child{margin-right:4px}.forge-layout,.arena-layout{display:flex;flex-direction:column}.forge-scene{height:220px}.side-column{gap:10px}.equipped-panel,.salvage-panel{padding-bottom:10px}.arena-stage{height:245px}.opponent-panel{padding:15px}.arena-note{margin-bottom:4px}.reliquary-panel .panel-heading{padding:18px}.collection-grid{grid-template-columns:repeat(2,minmax(0,1fr));padding:0 14px}.collection-card{padding:11px;min-height:100px}.collection-card strong{font-size:10px}footer{height:58px;font-size:7px;gap:6px;letter-spacing:.7px}.strike-card,.result-card{padding:25px 20px}.combat-actions{padding:10px}.secondary-button{padding:0 12px}}
@media(max-width:380px){.tab{padding:0 6px;font-size:7px}.reputation>b{font-size:7px}.recipe-stats{gap:7px;font-size:7px}.scene-caption{font-size:6px}.collection-grid{grid-template-columns:1fr}}

(() => {
  'use strict';
  const $ = (id) => document.getElementById(id);
  const gearCatalog = {
    blade: {name:'Cinderbound Blade',icon:'⚔',base:4,cost:2,kind:'weapon',difficulty:'STEADY'},
    buckler: {name:'Ashen Buckler',icon:'🛡',base:3,cost:2,kind:'armor',difficulty:'STEADY'},
    maul: {name:'Emberfall Maul',icon:'🔨',base:6,cost:3,kind:'weapon',difficulty:'TRICKY'},
    spear: {name:'Coalspire Spear',icon:'🔱',base:5,cost:2,kind:'weapon',difficulty:'STEADY'}
  };
  const rarityData = [
    {name:'Common',class:'common',mult:1,scrap:1}, {name:'Uncommon',class:'uncommon',mult:1.55,scrap:2},
    {name:'Rare',class:'rare',mult:2.2,scrap:3}, {name:'Epic',class:'epic',mult:3.1,scrap:5},
    {name:'Legendary',class:'legendary',mult:4.4,scrap:8}
  ];
  const recipes = Object.keys(gearCatalog);
  const foes = [
    {name:'Pit Guard',title:'PIT GUARD',icon:'🛡️',hp:22,damage:4,desc:'A veteran of the cinder pits. No tricks, just a heavy shield.',scrap:2,reward:'Worn Iron Buckler',gear:'buckler',rarity:0},
    {name:'Rook the Riveter',title:'ROOK THE RIVETER',icon:'🪓',hp:30,damage:5,desc:'A broad-shouldered brawler who fights with a salvaged axe.',scrap:3,reward:'Riveter’s Handaxe',gear:'maul',rarity:1},
    {name:'Sable Duelist',title:'SABLE DUELIST',icon:'🗡️',hp:38,damage:6,desc:'Quick as a spark, Sable never gives the arena a second chance.',scrap:4,reward:'Duelist’s Edge',gear:'blade',rarity:2},
    {name:'The Gilded Knight',title:'GILDED KNIGHT',icon:'🤺',hp:48,damage:7,desc:'A champion in gold-plated steel. This is no ordinary bout.',scrap:5,reward:'Sunforged Greatsword',gear:'spear',rarity:3},
    {name:'Ashen Wyrm',title:'ASHEN WYRM',icon:'🐉',hp:60,damage:8,desc:'An ancient beast awakened beneath the foundry. Forge a legend.',scrap:7,reward:'Wyrmheart Relic',gear:'maul',rarity:4}
  ];
  const initial = () => ({gold:120,scrap:4,wins:0,recipe:0,round:0,hp:30,maxHp:30,guard:false,collection:[{id:'starter',name:'Cinderbound Blade',icon:'⚔',power:4,rarity:0,kind:'weapon',equipped:true,source:'Starter gear'}],lastResult:null});
  let state = load(); let forgeTimer=null,forgeRaf=0,forgeStart=0,forgeDir=1,forgePos=4,toastTimer;
  function load(){try{const data=JSON.parse(localStorage.getItem('ember-iron-save'));if(data&&Array.isArray(data.collection)&&typeof data.gold==='number')return {...initial(),...data};}catch{}return initial()}
  function save(){localStorage.setItem('ember-iron-save',JSON.stringify(state));}
  function rarity(item){return rarityData[item.rarity]||rarityData[0]}
  function equipped(){return state.collection.filter(item=>item.equipped)}
  function power(){return equipped().reduce((n,item)=>n+item.power,0)}
  function showToast(message){const el=$('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300)}
  function switchView(name){document.querySelectorAll('.tab').forEach(tab=>tab.classList.toggle('active',tab.dataset.view===name));document.querySelectorAll('.view').forEach(view=>view.classList.toggle('active',view.id===`view-${name}`));if(name==='reliquary')renderCollection();if(name==='arena')renderArena();}
  document.querySelectorAll('.tab').forEach(tab=>tab.addEventListener('click',()=>switchView(tab.dataset.view)));
  function render(){
    $('gold-count').textContent=state.gold;$('scrap-count').textContent=state.scrap;
    $('recipe-name').textContent=gearCatalog[recipes[state.recipe]].name;$('recipe-power').textContent=`+${gearCatalog[recipes[state.recipe]].base}`;$('recipe-cost').textContent=gearCatalog[recipes[state.recipe]].cost;$('recipe-difficulty').textContent=gearCatalog[recipes[state.recipe]].difficulty;
    $('forge-cost').textContent=`· ${gearCatalog[recipes[state.recipe]].cost} SCRAP`;
    $('forge-hint').textContent=state.scrap<gearCatalog[recipes[state.recipe]].cost?'Not enough scrap. Salvage gear or win a bout.':'Strike when the ring glows for a chance at a rare result.';
    $('start-forge').disabled=state.scrap<gearCatalog[recipes[state.recipe]].cost;
    $('tool-art').textContent=gearCatalog[recipes[state.recipe]].icon;
    const items=equipped();$('gear-count').textContent=`${items.length} / 3`;$('power-total').textContent=power();
    $('equipped-list').innerHTML=items.map(item=>`<div class="gear-card"><span class="gear-art">${item.icon}</span><div class="gear-info"><strong>${esc(item.name)}</strong><small class="rarity-${rarity(item).class}">${rarity(item).name} · ${item.kind}</small></div><b class="gear-power">⚔ +${item.power}</b></div>`).join('')||'<div class="empty-state">No gear equipped. Forge a weapon.</div>';
    const spare=state.collection.filter(item=>!item.equipped);
    $('salvage-list').innerHTML=spare.slice(-3).reverse().map(item=>`<div class="salvage-card"><span class="gear-art">${item.icon}</span><div class="gear-info"><strong>${esc(item.name)}</strong><small class="rarity-${rarity(item).class}">${rarity(item).name} · +${rarity(item).scrap} scrap</small></div><button data-salvage="${item.id}">BREAK</button></div>`).join('')||'<div class="salvage-copy">No spare gear yet. Bring home a trophy from the arena.</div>';
    $('relic-count').textContent=state.collection.length;$('collection-total').textContent=state.collection.length;
    const winInRound=state.wins>=foes.length?foes.length-1:state.wins;
    $('rep-count').textContent=`${state.wins} / ${foes.length} WINS`;$('rep-fill').style.width=`${Math.min(100,state.wins/foes.length*100)}%`;
    $('rank-label').textContent=state.wins>=5?'ARENA LEGEND':state.wins>=3?'PIT CHAMPION':state.wins>=1?'CINDER CONTENDER':'ASHEN APPRENTICE';
    $('arena-alert').style.display=state.hp<=0?'inline':'none';renderArena();
  }
  function renderCollection(){const grid=$('collection-grid');if(!state.collection.length){grid.innerHTML='<div class="empty-state"><span>◇</span>Your reliquary is waiting for its first trophy.</div>';return}grid.innerHTML=state.collection.slice().reverse().map(item=>`<div class="collection-card"><span class="collection-emoji">${item.icon}</span><small class="rarity-${rarity(item).class}">${rarity(item).name.toUpperCase()} · ${item.kind.toUpperCase()}</small><strong>${esc(item.name)}</strong><small>POWER +${item.power} · ${item.equipped?'EQUIPPED':esc(item.source||'Forged at the old anvil')}</small></div>`).join('')}
  function renderArena(){const index=Math.min(state.wins,foes.length-1),foe=foes[index];$('round-label').textContent=state.wins>=foes.length?'CHAMPION':'ROUND '+(index+1);$('arena-title').textContent=state.wins>=foes.length?'The Crown of Cinders':'The Emberpit';$('opponent-card-name').textContent=state.wins>=foes.length?'Arena conquered':foe.name;$('opponent-desc').textContent=state.wins>=foes.length?'The arena bows to its new champion. Keep forging, keep fighting.':foe.desc;$('opponent-threat').textContent='★'.repeat(Math.min(3,index+1))+'☆'.repeat(Math.max(0,2-index));$('opponent-scrap').textContent=foe.scrap;$('opponent-reward').textContent=foe.reward;$('enemy-name').textContent=foe.title;$('enemy-avatar').textContent=foe.icon;$('player-health-text').textContent=`${Math.max(0,state.hp)} / ${state.maxHp} HP`;$('player-health').style.width=`${Math.max(0,state.hp)/state.maxHp*100}%`;
    if(state.encounterRound!==index){state.encounterRound=index;state.enemyHp=foe.hp;state.log='Step into the pit and let your steel speak.';state.guard=false;save()}
    state.enemyHp=Math.min(state.enemyHp??foe.hp,foe.hp);$('enemy-health-text').textContent=`${Math.max(0,state.enemyHp)} / ${foe.hp} HP`;$('enemy-health').style.width=`${Math.max(0,state.enemyHp)/foe.hp*100}%`;$('combat-log').innerHTML=`<span class="log-star">✦</span><span>${esc(state.log||'Step into the pit and let your steel speak.')}</span>`;
    const beaten=state.wins>=foes.length;const playerDown=state.hp<=0;$('attack-button').disabled=beaten||playerDown;$('guard-button').disabled=beaten||playerDown;$('drink-button').disabled=state.gold<10||state.hp>=state.maxHp||beaten;
    $('attack-button').innerHTML=beaten?'<span>✦</span> ARENA CONQUERED':playerDown?'<span>✚</span> REST BEFORE FIGHTING':'<span>⚔</span> ATTACK <b>YOUR TURN</b>';
    if(playerDown)$('combat-log').innerHTML='<span class="log-star">✦</span><span>You need a moment to recover. Restore health or return after resting.</span>';
  }
  function esc(value){return String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]))}
  $('cycle-recipe').addEventListener('click',()=>{state.recipe=(state.recipe+1)%recipes.length;render();save()});
  $('start-forge').addEventListener('click',startForge);
  function startForge(){const recipe=gearCatalog[recipes[state.recipe]];if(state.scrap<recipe.cost)return;state.scrap-=recipe.cost;save();render();$('strike-overlay').classList.add('open');$('strike-overlay').setAttribute('aria-hidden','false');forgeStart=performance.now();forgePos=3;forgeDir=1;function move(now){if(!$('strike-overlay').classList.contains('open'))return;const elapsed=now-forgeStart;forgePos=3+(Math.sin(elapsed/445)*.5+.5)*94;$('timing-marker').style.left=`${forgePos}%`;forgeRaf=requestAnimationFrame(move)}forgeRaf=requestAnimationFrame(move);$('strike-button').focus()}
  $('strike-button').addEventListener('click',strike);document.addEventListener('keydown',event=>{if(event.code==='Space'&&$('strike-overlay').classList.contains('open')){event.preventDefault();strike()}if(event.key==='Escape')closeOverlays()});
  function strike(){if(!$('strike-overlay').classList.contains('open'))return;cancelAnimationFrame(forgeRaf);$('strike-overlay').classList.remove('open');$('strike-overlay').setAttribute('aria-hidden','true');const marker=forgePos;const quality=Math.max(0,1-Math.abs(marker-50)/50);const perfect=marker>=42&&marker<=58;const recipe=gearCatalog[recipes[state.recipe]];$('hammer-art').classList.add('hit');$('forge-scene').classList.add('hot');setTimeout(()=>{$('hammer-art').classList.remove('hit');$('forge-scene').classList.remove('hot')},300);
    const failChance=perfect?.04:.24-quality*.12;const roll=Math.random();if(roll<failChance){showResult({success:false,quality,perfect,recipe});return}let rarityIndex=0;if(perfect){rarityIndex=roll>.93?4:roll>.71?3:roll>.39?2:1}else if(quality>.78){rarityIndex=roll>.94?3:roll>.66?2:roll>.28?1:0}else if(quality>.45){rarityIndex=roll>.90?2:roll>.53?1:0}const item={id:`gear-${Date.now()}-${Math.floor(Math.random()*999)}`,name:rarityIndex>=3?['Cinderbound Blade','Ashen Buckler','Emberfall Maul','Coalspire Spear'][recipes.indexOf(Object.keys(gearCatalog).find(key=>gearCatalog[key]===recipe))]+' of the '+(rarityIndex===4?'First Flame':'Living Ember'):recipe.name,icon:recipe.icon,power:Math.max(1,Math.round(recipe.base*rarityData[rarityIndex].mult)),rarity:rarityIndex,kind:recipe.kind,equipped:false,source:'Forged at the old anvil'};
    if(equipped().length<3)item.equipped=true;state.collection.push(item);if(rarityIndex>=3)state.gold+=15;save();render();showResult({success:true,quality,perfect,item});
  }
  function showResult(data){const modal=$('result-modal');modal.classList.add('open');if(!data.success){$('result-icon').textContent='⚒';$('result-eyebrow').textContent='THE STEEL CRACKED';$('result-title').textContent='A costly miss';$('result-copy').textContent='The strike rang wrong and the piece collapsed. Some scrap is lost, but the next swing could be the one.';$('result-item').textContent=`-${gearCatalog[recipes[state.recipe]].cost} scrap · Try again`;return}$('result-icon').textContent=data.item.icon;$('result-eyebrow').textContent=data.perfect?'MASTERFUL STRIKE':'FORGE COMPLETE';$('result-title').textContent=data.perfect?'The anvil sang.':'A fine piece of steel';$('result-copy').textContent=data.perfect?'A perfectly timed blow. This is the kind of craft bards remember.':data.quality>.7?'A clean strike and a strong result.':'The steel holds, though there is room to improve.';$('result-item').innerHTML=`<span class="rarity-${rarity(data.item).class}">${rarity(data.item).name}</span> &nbsp; ${esc(data.item.name)} &nbsp; · &nbsp; ⚔ +${data.item.power}`}
  function closeOverlays(){$('result-modal').classList.remove('open');$('strike-overlay').classList.remove('open');cancelAnimationFrame(forgeRaf)}$('close-result').addEventListener('click',closeOverlays);$('result-continue').addEventListener('click',closeOverlays);$('result-modal').addEventListener('click',event=>{if(event.target===$('result-modal'))closeOverlays()});
  $('salvage-list').addEventListener('click',event=>{const button=event.target.closest('[data-salvage]');if(!button)return;const item=state.collection.find(gear=>gear.id===button.dataset.salvage);if(!item||item.equipped)return;state.scrap+=rarity(item).scrap;state.collection=state.collection.filter(gear=>gear.id!==item.id);save();render();showToast(`${item.name} salvaged for ${rarity(item).scrap} scrap.`)});
  function enemyTurn(foe){const dmg=Math.max(1,foe.damage+Math.floor(Math.random()*3)-Math.floor(power()/9));if(state.guard){const taken=Math.max(0,Math.floor(dmg*.35));state.hp=Math.min(state.maxHp,state.hp-taken+3);state.log=`You brace behind your guard. ${taken} damage taken, and you recover 3 HP.`;state.guard=false}else{state.hp-=dmg;state.log=`${foe.name} lands a hit for ${dmg} damage.`}$('arena-stage').classList.add('shake');setTimeout(()=>$('arena-stage').classList.remove('shake'),300);save();render()}
  $('attack-button').addEventListener('click',()=>{if(state.hp<=0||state.wins>=foes.length)return;const index=Math.min(state.wins,foes.length-1),foe=foes[index];const dmg=Math.max(2,power()+Math.floor(Math.random()*4)-1);state.enemyHp-=dmg;if(state.enemyHp<=0){state.enemyHp=0;state.wins++;state.gold+=12+index*5;state.hp=Math.min(state.maxHp,state.hp+8);state.log=`Victory! ${foe.name} falls. You collect gold, recover 8 HP, and claim their gear.`;const item={id:`trophy-${Date.now()}`,name:foe.reward,icon:foe.icon,power:Math.max(2,Math.round(gearCatalog[foe.gear].base*rarityData[foe.rarity].mult)),rarity:foe.rarity,kind:gearCatalog[foe.gear].kind,equipped:false,source:`Won from ${foe.name}`};state.collection.push(item);if(equipped().length<3)item.equipped=true;state.encounterRound=-1;save();render();$('arena-stage').classList.add('victory');setTimeout(()=>$('arena-stage').classList.remove('victory'),600);showToast(`Victory! ${foe.reward} added to your reliquary.`);return}state.log=`Your gear strikes for ${dmg} damage.`;enemyTurn(foe)});
  $('guard-button').addEventListener('click',()=>{if(state.hp<=0||state.wins>=foes.length)return;state.guard=true;const foe=foes[Math.min(state.wins,foes.length-1)];state.log='You raise your guard. The next blow will be softened and you’ll catch your breath.';enemyTurn(foe)});
  $('drink-button').addEventListener('click',()=>{if(state.gold<10||state.hp>=state.maxHp)return;state.gold-=10;state.hp=Math.min(state.maxHp,state.hp+8);state.log='You take a restorative draught. The fight can continue.';save();render();showToast('Restored 8 HP.')});
  $('reset-game').addEventListener('click',()=>{if(!confirm('Start a new legend? Your current progress will be lost.'))return;state=initial();save();render();switchView('forge');showToast('A fresh spark. Make it count.')});
  render();
})();

