tent:center}.forge-scene:before{content:'';position:absolute;inset:auto 0 0;height:80px;background:linear-gradient(0deg,#100e0c,#17141100);z-index:2}.scene-glow{position:absolute;width:270px;height:180px;bottom:15px;background:radial-gradient(ellipse,#d95d29aa,#a43d2677 22%,transparent 68%);filter:blur(16px);transition:.3s}.forge-scene.hot .scene-glow{background:radial-gradient(ellipse,#ff9a37dd,#d44e24aa 28%,transparent 70%);transform:scale(1.3)}.forge-window{position:absolute;top:15px;width:132px;height:110px;border:6px solid #5b4532;border-bottom:0;border-radius:68px 68px 0 0;background:linear-gradient(#1b1714,#3d2418 75%,#c95425);box-shadow:inset 0 0 18px #e75a2580}.forge-arch{position:absolute;inset:9px 10px 0;border:1px solid #b76436;border-bottom:0;border-radius:50px 50px 0 0;overflow:hidden}.flame{position:absolute;bottom:0;color:#ffb24c;text-shadow:0 0 14px #f86;font-size:52px;animation:flicker .7s ease-in-out infinite alternate}.flame-one{left:15px}.flame-two{right:11px;animation-delay:.3s;color:#e45729}@keyframes flicker{to{transform:scale(1.12) translateY(-4px);filter:brightness(1.3)}}.forge-embers{position:absolute;left:15%;top:24px;color:#efa46288;font-size:18px;letter-spacing:9px}.tool-silhouette{position:absolute;bottom:66px;left:calc(50% - 35px);z-index:2;color:#ee9c47;font-size:61px;text-shadow:0 0 20px #ff8a36;filter:drop-shadow(0 5px 3px #160e0a)}.anvil{position:absolute;z-index:3;bottom:32px;width:144px;height:65px}.anvil-top{height:16px;background:linear-gradient(#b1a597,#645b51);clip-path:polygon(10% 12%,85% 12%,100% 50%,72% 100%,0 90%);border-radius:3px}.anvil-body{width:80px;height:35px;margin:-1px auto 0;background:linear-gradient(90deg,#544d46,#8b8175,#403a34);clip-path:polygon(10% 0,90% 0,75% 100%,28% 100%)}.anvil-foot{height:8px;width:57px;margin:-1px auto;background:#62584f;border-radius:2px}.hammer{position:absolute;z-index:5;right:calc(50% - 88px);bottom:89px;font-size:37px;transform:rotate(-27deg);filter:drop-shadow(2px 5px 4px #0908